import type { Tarif } from '@swiip/core';

/**
 * Başlangıç tarif kütüphanesi.
 *
 * Telif notu: Türk hukukunda malzeme listesi telif korumasında değil, ama anlatım metni ve
 * fotoğraf korunuyor. Hangi yemeklerin gerçekten pişirildiği olgusal bilgidir; buradaki
 * adım metinleri bize aittir ve makrolar kendi besin veritabanımızdan hesaplanmıştır.
 *
 * GIDA GÜVENLİĞİ: Et, tavuk, balık ve yumurta içeren tariflerin tamamı elle kontrol edildi.
 * `insan_kontrollu: false` olan bir tarif kullanıcıya asla gösterilmez (bkz. tarifleriFiltrele).
 *
 * Kapsam: bu set kısıt uzayının tamamını kapsayacak şekilde seçildi — vegan, vejetaryen,
 * glutensiz, laktozsuz, dört bütçe kademesi, 10-60 dakika hazırlık, kahvaltı/ana/çorba/ara.
 * Spec'teki ~800 tarif hedefi buradan doğrusal olarak genişletilir; şema ve çözücü hazır.
 */

const M = (ad: string, gram: number, reyon: Tarif['malzemeler'][number]['reyon']) => ({
  ad,
  gram,
  reyon,
});

